"""Cuaderno del estudiante, 4.º básico Lenguaje y Comunicación, OA 18 (revisión y edición con propósito) y OA 19 (adverbios).

Todos los textos son originales y breves; cada ejercicio trae el texto que necesita.
Nota: en el currículo del repositorio el texto oficial citado bajo OA 18 (incorporar vocabulario nuevo)
no coincide con el título de la secuencia (revisión y edición); este cuaderno sigue el título y las
clases, e incorpora el vocabulario nuevo en la clase 4.
"""
from __future__ import annotations

from student_lessons import arith, ex, register

OA18, OA19 = "LE04 OA 18", "LE04 OA 19"
E = ex


def task(statement, example, criteria, evidence, errors, feedback):
    return {"statement": statement, "example": example, "criteria": criteria, "evidence": evidence, "errors": errors, "feedback": feedback}


def L(oa, n, materials, use, prior, explain, vocab, worked, mistakes, tiers, ctx, sc, open_task, reinforce, extend):
    register(
        oa, n, materials=materials, use=use, prior=prior, explain=explain, vocab=vocab,
        worked=[{"title": t, "problem": p, "steps": s, "answer": a} for t, p, s, a in worked],
        mistakes=[{"wrong": w, "why": y, "fix": f} for w, y, f in mistakes],
        tiers=dict(zip(("recovery", "understand", "apply", "reason", "challenge"), tiers)),
        context=ctx, selfcheck=sc, open_task=task(*open_task), reinforce=reinforce, extend=extend,
    )


# ------------------------------------------------------------------ OA 18
L(OA18, 1,
  "Este cuaderno, lápiz y los borradores escritos en cada ejercicio.",
  "Aprenderé a revisar primero si mi texto cumple su propósito y se entiende, antes de corregir las letras y los puntos.",
  ["Sé decidir el propósito y el destinatario de un texto.", "Sé qué es un párrafo."],
  ["Revisar es leer de nuevo tu propio texto para mejorarlo. Editar es hacer los cambios. Cada vez que escribes el texto con cambios, tienes una versión nueva. Lo primero que se revisa es el sentido: ¿el texto dice lo que querías y se entiende?",
   "Para revisar el sentido, hazte tres preguntas. ¿Cumple mi propósito? ¿Tiene todas las ideas necesarias? ¿Tiene ideas que sobran o que no se entienden? Solo después conviene revisar mayúsculas, puntos, tildes y ortografía.",
   "Si cambias primero las letras y luego descubres que falta una idea, tendrás que volver a escribir. Por eso se revisa de lo grande a lo pequeño: primero el sentido de todo el texto y después los detalles."],
  [("revisar", "leer mi texto de nuevo para mejorarlo"), ("editar", "hacer los cambios que mejoran el texto"), ("versión", "cada vez que escribo el texto con cambios"), ("sentido", "lo que el texto quiere decir"), ("idea que sobra", "idea que no sirve al propósito")],
  [("Revisar el propósito", "Quieres invitar a tu curso a una obra, pero escribiste: «Ayer vi una obra muy larga». ¿Cumple el propósito?", ["Mi propósito es invitar.", "El texto solo cuenta lo que vi.", "No dice día ni lugar, y no invita."], "No cumple; falta invitar y dar datos"),
   ("Encontrar la idea que sobra", "Lee: «Compré pan. Pagué en la caja. Mi gato duerme en el sillón». El texto es sobre la compra de pan. ¿Qué idea sobra?", ["El tema es la compra de pan.", "«Pagué en la caja» es parte de la compra.", "El gato no tiene relación."], "Mi gato duerme en el sillón")],
  [("Corregir tildes antes de ver si el texto se entiende.", "Tal vez después cambies partes enteras.", "Revisa el sentido primero."), ("Creer que revisar es copiar de nuevo igual.", "La versión nueva debe mejorar.", "Cada versión corrige algo.")],
  ([E("Cuando revisas el sentido, ¿miras si el texto se entiende o si hay manchas de lápiz?", "Si el texto se entiende", "El sentido es lo que el texto comunica."),
    E("Un borrador no dice para qué fue escrito. ¿Qué parte del sentido falta: el propósito o el margen?", "El propósito", "El propósito es la razón por la que se escribe."),
    E("Si una oración no tiene relación con el tema, ¿sobra o falta?", "Sobra", "Una idea sin relación sobra en el texto.")],
   [E("Lee: «Mi escuela tiene un patio grande. Tiene árboles y bancos. Mi tía vende verduras». El propósito es describir la escuela. ¿Qué oración sobra?", "Mi tía vende verduras", "No habla de la escuela."),
    E("Lee: «Se pide traer un cuaderno». No dice cuándo. ¿Qué problema de sentido tiene: falta información o sobra información?", "Falta información", "No se sabe para cuándo."),
    E("¿Cuál es una pregunta para revisar el sentido: «¿Cumple mi propósito?» o «¿Usé lápiz azul?»", "¿Cumple mi propósito?", "Esa pregunta revisa si el texto logra lo que busca.")],
   [E("Lee: «El perro de Sofía se llama Nube. Es blanco y juguetón. Mañana lloverá». El propósito es describir al perro. Copia la oración que sobra.", "Mañana lloverá", "No describe al perro."),
    E("Lee: «Quiero invitarte a mi cumpleaños. Será en mi casa. Trae ganas de jugar». ¿Qué dato falta: el día y la hora o el nombre de tu colegio?", "El día y la hora", "Sin día y hora no se puede ir."),
    E("Lee: «Fui al parque. Jugué con Pedro. Me caí. Tengo un perro. Me levanté». El propósito es contar lo que pasó en el parque. ¿Cuántas oraciones sobran?", "1", "Solo «Tengo un perro» no cuenta lo del parque.")],
   [E("Lucía debe hacer dos cosas: a) corregir tildes y puntos, b) comprobar que el texto cumple su propósito. ¿Cuál va primero?", "b", "Primero se revisa el sentido."),
    E("Pedro dice: «Mi carta está lista, no tiene faltas». Rosa responde: «Pero no dice qué pides». ¿Quién revisó el sentido?", "Rosa", "Ella se fijó en si el texto cumple su propósito.")],
   [E("Lee: «Para cuidar el parque no hay que botar basura. Además, hay que regar las flores. También me gusta el helado». El propósito es pedir que cuiden el parque. ¿Cuántas ideas sirven?", "2", "Sirven la basura y las flores; el helado sobra."),
    E("Lee: «Querida directora: Hay un problema. Mi gato se llama Rufo. Gracias». Quieres pedir que arreglen un bebedero. ¿Qué debe cambiar: decir qué se pide o contar más del gato?", "Decir qué se pide", "El texto no dice el pedido.")],
   ),
  [E("Escribes: «Te espero en la plaza». ¿Qué dato falta para que se entienda: el día y la hora o el color de la plaza?", "El día y la hora", "Sin esos datos no se sabe cuándo ir.")],
  [E("¿Qué se revisa primero: el sentido o las tildes?", "El sentido", "Se revisa de lo grande a lo pequeño."),
   E("Una idea que no sirve al propósito, ¿se deja o se quita?", "Se quita", "Sobra en el texto."),
   E("¿Qué es una versión de un texto?", "Cada texto con cambios", "Es cada vez que lo reescribo con mejoras.")],
  ("Lee este borrador: «Quiero invitarte a jugar. Mi lápiz es amarillo. Será pronto.» Tu propósito es invitar a un amigo a jugar luche el sábado a las 5 en la plaza. Haz una versión nueva que cumpla el propósito. Quita lo que sobra y agrega lo que falta.", "«Quiero invitarte a jugar luche el sábado a las 5 en la plaza».", ["incluye día, hora y lugar", "quita la idea que sobra", "mantiene el propósito de invitar"], ["una versión nueva escrita en el cuaderno"], ["agregar datos sin quitar lo que sobra", "arreglar ortografía antes de revisar el sentido"], "Lee tu versión a otra persona y pregúntale si sabe cuándo y dónde ir."),
  "Relee un texto tuyo y marca una idea que sobra.",
  "Escribe un borrador de tres oraciones, revisa su sentido y haz una versión mejor.")

L(OA18, 2,
  "Este cuaderno, lápiz y los textos de cada ejercicio.",
  "Aprenderé a organizar las ideas en párrafos separados, usando punto aparte para cerrar cada párrafo.",
  ["Sé que un texto tiene oraciones.", "Sé revisar el sentido de un texto."],
  ["Un párrafo es un grupo de oraciones que hablan de una misma idea. Cuando cambias de idea, empiezas otro párrafo. Para eso se usa el punto aparte: terminas la oración con un punto, bajas a la línea de abajo y empiezas con mayúscula.",
   "Si un texto cuenta un paseo, un párrafo puede contar la salida, otro lo que hicieron y otro la vuelta. Cada párrafo tiene una idea principal. Así el lector encuentra rápido cada parte.",
   "Un texto pegado, sin separaciones, cansa al lector. Y un texto con una oración por línea queda desordenado. Lo ideal es agrupar las oraciones que hablan de lo mismo y separar cuando cambia el tema."],
  [("párrafo", "grupo de oraciones sobre una misma idea"), ("punto aparte", "punto al terminar un párrafo; se sigue en otra línea"), ("idea principal", "lo más importante que dice el párrafo"), ("separar", "dividir en partes")],
  [("Separar en párrafos", "Texto: «Fuimos al parque. Subimos a los columpios. Después fuimos a la casa de Luis. Tomamos jugo». ¿Dónde empieza el segundo párrafo?", ["Las dos primeras oraciones hablan del parque.", "Después cambia el lugar: la casa de Luis.", "Ahí empieza otra idea."], "En «Después fuimos a la casa de Luis»"),
   ("Encontrar la idea principal", "Párrafo: «Mi gato duerme mucho. Duerme en el sillón y en mi cama. Duerme casi todo el día». ¿Cuál es su idea principal?", ["Las tres oraciones hablan de lo mismo.", "Todas dicen que el gato duerme."], "Mi gato duerme mucho")],
  [("Escribir todo el texto en un solo bloque.", "El lector no ve cuándo cambia la idea.", "Separa cuando cambia el tema."), ("Cambiar de línea después de cada oración.", "Las ideas que van juntas quedan separadas.", "Agrupa las oraciones del mismo tema.")],
  ([E("Un grupo de oraciones sobre una misma idea es un…", "Párrafo", "Eso es un párrafo."),
    E("Para terminar un párrafo, ¿se usa punto seguido o punto aparte?", "Punto aparte", "El punto aparte cierra el párrafo."),
    E("Después del punto aparte, ¿la oración nueva empieza con mayúscula? Responde sí o no.", "Sí", "Toda oración nueva comienza con mayúscula.")],
   [E("Lee: «Nos levantamos temprano. Tomamos desayuno. Luego fuimos a la playa. Nadamos en el mar». ¿En cuántos párrafos conviene dividirlo si uno trata de la casa y otro de la playa?", "2", "Hay dos temas: la casa y la playa."),
    E("Lee el párrafo: «El zorro corrió. El zorro saltó la reja. El zorro llegó al gallinero». ¿Cuál es su idea principal: el zorro llegó al gallinero o el zorro es astuto?", "El zorro llegó al gallinero", "Las oraciones cuentan cómo llega al gallinero."),
    E("Un texto de seis oraciones está en un solo bloque, aunque habla de dos temas. ¿Qué falta: punto aparte o un título más largo?", "Punto aparte", "Hay que separar los párrafos cuando cambia el tema.")],
   [E("Un texto tiene estas oraciones: 1) Mi escuela es grande. 2) Tiene un patio con árboles. 3) En el recreo jugamos fútbol. 4) Mi profesora se llama Ana. ¿Con qué oración conviene empezar el segundo párrafo si el primero describe la escuela?", "3", "La oración 3 empieza a hablar del recreo."),
    E("Lee: «Marta tiene un perro. Se llama Tito. Es muy juguetón. Marta tiene un gato. Se llama Mimi. Es muy tranquila». ¿Cuántos párrafos tendría si cada animal tiene el suyo?", "2", "Uno para el perro y uno para el gato."),
    E("Un párrafo dice: «La lluvia cayó. Las calles se mojaron. Los niños corrieron adentro». ¿Dónde pondrías el punto aparte si ahora cambias a hablar del sol?", "Después de «adentro»", "Allí termina la idea de la lluvia.")],
   [E("Un niño escribe cada oración en una línea distinta, aunque todas hablan de lo mismo. ¿Qué error cometió: usó demasiados puntos aparte o demasiado pocos?", "Demasiados puntos aparte", "Las oraciones del mismo tema deben ir juntas."),
    E("Camila escribió un solo párrafo con tres ideas: el paseo, la comida y la vuelta. Su compañero dice que conviene dividirlo en tres. ¿Tiene razón? Responde sí o no.", "Sí", "Cada idea principal necesita su propio párrafo.")],
   [E("Ordena en dos párrafos estas oraciones: a) Fuimos a la feria. b) Compramos frutas. c) Ya en casa hicimos jugo. d) Todos tomamos un vaso. Escribe el número de oraciones del primer párrafo si este cuenta la feria.", "2", "Las oraciones a y b cuentan la feria; c y d, la casa."),
    E("En un texto, el punto aparte aparece cuando la idea cambia. Si un texto cambia de idea 2 veces, ¿cuántos párrafos tiene?", "3", "Dos cambios dividen el texto en tres partes.")]),
  [E("Escribes una carta a un amigo con tres ideas: saludo, lo que hiciste en vacaciones y la despedida. ¿Cuántos párrafos conviene usar?", "3", "Cada idea ocupa un párrafo.")],
  [E("¿Qué es un párrafo?", "Un grupo de oraciones sobre una misma idea", "Todas tratan del mismo tema."),
   E("¿Qué signo cierra un párrafo?", "El punto aparte", "Después se sigue en otra línea."),
   E("Si cambio de idea, ¿empiezo otro párrafo? Responde sí o no.", "Sí", "Cada idea principal tiene su párrafo.")],
  ("Lee este texto sin separaciones: «Hoy fuimos a la biblioteca. Pedimos libros de animales. Vimos fotos de ballenas y delfines. Después volvimos al colegio. Almorzamos en el patio. Jugamos a la pelota». Reescríbelo en dos párrafos con punto aparte y escribe la idea principal de cada uno.", "Párrafo 1 (biblioteca): las primeras tres oraciones. Párrafo 2 (colegio): las tres últimas.", ["separa en dos párrafos", "usa punto aparte y mayúscula", "escribe la idea principal de cada uno"], ["texto reescrito en dos párrafos"], ["cortar en medio de una idea", "no escribir la idea principal"], "Lee tus párrafos a otra persona y pregúntale cuándo cambió el tema."),
  "Mira un cuento de un libro y cuenta cuántos párrafos tiene una página.",
  "Escribe tres oraciones sobre tu casa y tres sobre tu barrio, y sepáralas en dos párrafos.")

L(OA18, 3,
  "Este cuaderno, lápiz y los textos de cada ejercicio.",
  "Aprenderé a usar conectores para unir ideas y mostrar orden, causa o contraste.",
  ["Sé separar un texto en párrafos.", "Sé que las oraciones se unen con palabras como «y»."],
  ["Un conector es una palabra o expresión que une oraciones o ideas y muestra su relación. Los hay de orden: primero, luego, después, finalmente. De causa: porque, ya que, por eso. De contraste: pero, sin embargo, aunque. Y de suma: además, también.",
   "Elegir bien el conector cambia el sentido. «Llegué tarde porque perdí el bus» explica una causa. «Llegué tarde, pero entré a la clase» muestra contraste. «Llegué tarde y después saludé» indica orden.",
   "No uses siempre el mismo conector. Repetir «y» o «entonces» cansa. Tampoco pongas un conector que no corresponda: «Me caí, además estoy bien» no tiene sentido; mejor «Me caí, pero estoy bien»."],
  [("conector", "palabra que une ideas y muestra su relación"), ("causa", "la razón de algo"), ("contraste", "diferencia entre dos ideas"), ("orden", "primero, luego, finalmente"), ("suma", "agregar una idea más")],
  [("Elegir un conector de causa", "Completa: «Me quedé en casa ___ llovía mucho». Opciones: porque, pero.", ["Llovía es la razón de quedarse.", "Una razón se une con «porque»."], "porque"),
   ("Elegir un conector de contraste", "Completa: «Quería salir, ___ no me dejaron». Opciones: por eso, pero.", ["La segunda idea contradice la primera.", "El conector de contraste es «pero»."], "pero")],
  [("Usar «y» para todo.", "El texto repite y no muestra relaciones.", "Elige conectores de orden, causa o contraste."), ("Poner un conector que no corresponde.", "Cambia el sentido de la frase.", "Pregunta qué relación tienen las ideas.")],
  ([E("«Porque» muestra una causa. Responde verdadero o falso.", "Verdadero", "Porque introduce la razón de algo."),
    E("¿Cuál es un conector de orden: «primero» o «porque»?", "Primero", "Primero indica el orden."),
    E("¿Cuál es un conector de contraste: «pero» o «luego»?", "Pero", "Pero muestra una diferencia entre dos ideas.")],
   [E("Completa: «Comí mucho ___ tenía hambre». Opciones: porque, pero.", "porque", "Tener hambre es la razón."),
    E("Completa: «Estudié, ___ saqué mala nota». Opciones: por eso, sin embargo.", "sin embargo", "Hay contraste: estudiar y aun así sacar mala nota."),
    E("Completa: «___ lavo la fruta; luego la corto». Opciones: Primero, Porque.", "Primero", "Indica el orden de dos pasos.")],
   [E("Completa: «Hacía frío; ___ me puse el abrigo». Opciones: por eso, pero.", "por eso", "El frío es la causa de ponerse el abrigo."),
    E("Completa: «Me gusta leer. ___, me gusta dibujar». Opciones: Además, Porque.", "Además", "Se suma otra idea."),
    E("Completa: «___ llegamos al lago; después armamos la carpa». Opciones: Finalmente, Primero.", "Primero", "Es el primer paso de los dos.")],
   [E("Una niña escribe: «Me caí, además estoy bien». ¿Qué conector corrige el sentido: pero o además?", "Pero", "Hay contraste entre caerse y estar bien."),
    E("Un texto repite «y» seis veces. ¿Qué conviene: cambiar algunos por conectores de orden o dejar todos?", "Cambiar algunos por conectores de orden", "Así el texto se lee con más variedad.")],
   [E("Une las oraciones con un conector de causa: «Cerré la ventana. Entraba mucho frío». ¿Cuál queda bien: «Cerré la ventana porque entraba mucho frío» o «Cerré la ventana pero entraba mucho frío»?", "Cerré la ventana porque entraba mucho frío", "El frío es la causa de cerrar."),
    E("Ordena con conectores: a) Finalmente, ya estaba listo. b) Primero, mezclé los ingredientes. c) Luego, lo puse en el molde. Escribe las letras en orden.", "b, c, a", "Primero, luego, finalmente.")]),
  [E("Escribes: «Quería ir al cine, ___ no tenía dinero». Opciones: por eso, pero.", "pero", "Hay contraste entre el deseo y la realidad.")],
  [E("¿Qué es un conector?", "Una palabra que une ideas", "Muestra la relación entre ellas."),
   E("¿Qué conector introduce la razón de algo: «porque» o «pero»?", "Porque", "Porque presenta la razón."),
   E("¿Para qué sirve «además»?", "Para sumar otra idea", "Agrega algo más.")],
  ("Lee este texto: «Fui al parque. Jugué con mi perro. Volví a casa». Reescríbelo usando al menos tres conectores distintos, por ejemplo uno de orden, uno de causa y uno de suma (por ejemplo, primero, porque, además), sin cambiar lo que cuenta.", "«Primero fui al parque porque hacía sol. Además, jugué con mi perro. Después volví a casa».", ["usa tres conectores distintos", "el sentido se mantiene", "las oraciones tienen sentido"], ["texto reescrito en el cuaderno"], ["usar siempre «y»", "conector que no corresponde"], "Lee tu texto a otra persona y pregúntale si entiende la relación entre las ideas."),
  "Busca tres conectores en un cuento y di qué relación muestran.",
  "Une tres pares de oraciones con conectores de causa, contraste y orden.")

L(OA18, 4,
  "Este cuaderno, lápiz y los textos y glosarios de cada ejercicio.",
  "Aprenderé a reemplazar palabras repetidas por otras más precisas y a incorporar vocabulario nuevo en mis textos.",
  ["Sé usar conectores.", "Sé buscar el significado de una palabra."],
  ["Un texto mejora cuando usas palabras variadas y precisas. Si repites «cosa», «bonito» o «hacer» muchas veces, el lector no sabe exactamente a qué te refieres. Una palabra precisa dice justo lo que quieres decir. Un sinónimo es otra palabra con un significado parecido.",
   "También conviene usar vocabulario nuevo que aprendiste al leer o escuchar. Si lees «admirar» o «asombro», puedes usar esas palabras en tus textos, pero solo si entiendes su significado. Si no estás seguro, búscalo en un diccionario.",
   "Revisa tu texto subrayando las palabras que se repiten. Cámbialas por sinónimos que mantengan el sentido. Por ejemplo, en vez de «El paisaje es bonito», puedes escribir «El paisaje es hermoso». Cuida que el cambio no altere lo que quieres decir."],
  [("vocabulario", "las palabras que conozco y uso"), ("sinónimo", "palabra con significado parecido a otra"), ("palabra precisa", "palabra que dice justo lo que quiero decir"), ("repetición", "usar muchas veces la misma palabra"), ("asombro", "sorpresa grande")],
  [("Cambiar una palabra repetida", "«Vi una cosa grande. La cosa era un barco». ¿Cómo mejoras?", ["Repite «cosa».", "En el primer caso es un barco.", "Digo directamente: Vi un barco grande."], "«Vi un barco grande»"),
   ("Usar vocabulario nuevo", "Aprendiste «asombro»: sorpresa grande. Completa: «Al ver el arcoíris, sentí ___». Opciones: asombro, hambre.", ["Ver un arcoíris sorprende.", "La palabra que significa sorpresa grande es asombro."], "asombro")],
  [("Cambiar una palabra por otra sin entender qué significa.", "El sentido puede cambiar o quedar raro.", "Revisa el significado antes de usarla."), ("Repetir «bonito» o «cosa» en todo el texto.", "No dice con precisión qué quieres expresar.", "Busca una palabra más precisa.")],
  ([E("Un sinónimo, ¿es una palabra con significado parecido? Responde sí o no.", "Sí", "Eso es un sinónimo."),
    E("Si repites mucho «cosa», ¿tu texto es más preciso o menos preciso?", "Menos preciso", "«Cosa» no dice exactamente de qué hablas."),
    E("Antes de usar una palabra nueva, ¿qué debes saber: su significado o su color?", "Su significado", "Hay que usarla en el sentido correcto.")],
   [E("En «Vi un perro bonito y una casa bonita», ¿qué palabra se repite?", "Bonito", "Aparece dos veces."),
    E("¿Cuál palabra es sinónimo de «hermoso»: «lindo» o «ruidoso»?", "Lindo", "Ambas significan que algo es agradable de ver."),
    E("Reemplaza «cosa» por una palabra precisa en: «Guardé la cosa de dibujar en la mochila». Opciones: cuaderno, mañana.", "cuaderno", "Un cuaderno se usa para dibujar.")],
   [E("Completa con una palabra precisa: «El gato ___ por el techo». Opciones: caminó, ruidoso.", "caminó", "Se necesita un verbo, no un adjetivo."),
    E("El glosario dice: «admirar: mirar con respeto algo que nos gusta». Completa: «Admiro a mi abuelo porque ___». Opciones: trabaja con esfuerzo, es ruidoso.", "trabaja con esfuerzo", "Se admira algo valioso."),
    E("Reemplaza «dijo» por una palabra más precisa en: ««¡Cuidado!», dijo la profesora». Opciones: gritó, sentó.", "gritó", "La exclamación se expresa con una voz fuerte.")],
   [E("Un niño reemplaza «grande» por «ancho» en «una montaña grande». ¿Cambió el sentido? Responde sí o no.", "Sí", "Una montaña ancha no es lo mismo que una grande."),
    E("«Rápido» y «veloz» son sinónimos. En «El auto es rápido», ¿puedes escribir «El auto es veloz» sin cambiar el sentido? Responde sí o no.", "Sí", "Las dos significan que va a gran velocidad.")],
   [E("Lee: «El oso era grande y el perro era grande. El gato también era grande». Reescribe usando dos palabras distintas para «grande». ¿Qué par sirve: enorme y gigante o frío y caliente?", "Enorme y gigante", "Ambas significan muy grande."),
    E("Glosario: «travesía: viaje largo». Completa: «La ___ por el mar duró dos semanas». Opciones: travesía, ventana.", "travesía", "Un viaje largo por el mar es una travesía.")]),
  [E("Escribes: «Me gusta mi gato porque es bonito y tiene un pelo bonito». ¿Qué cambias para no repetir: la segunda palabra «bonito» por «suave» o por «gritón»?", "Por «suave»", "Suave describe un pelo y mantiene el sentido.")],
  [E("¿Qué es un sinónimo?", "Una palabra con significado parecido", "Dice casi lo mismo."),
   E("¿Para qué cambiamos palabras repetidas?", "Para que el texto sea más variado y preciso", "Evita repetir y dice mejor lo que se quiere."),
   E("Antes de usar una palabra nueva, ¿qué hago si no estoy seguro de su significado?", "La busco en un diccionario", "Así la uso correctamente.")],
  ("Lee: «Fuimos a un lugar bonito. Había una cosa grande. La cosa era un árbol. Era bonito». Reescribe el texto cambiando las palabras repetidas por palabras precisas (por ejemplo, hermoso, enorme, parque). Mantén lo que cuenta y usa al menos una palabra que hayas aprendido en un texto reciente.", "«Fuimos a un parque hermoso. Había un árbol enorme. Era majestuoso».", ["cambia «bonito» y «cosa»", "mantiene el sentido", "agrega vocabulario nuevo correcto"], ["texto reescrito en el cuaderno"], ["cambiar sin entender el significado", "repetir otra palabra"], "Pide a otra persona que subraye la palabra que más le gustó."),
  "Busca una palabra nueva en un libro, anota su significado y úsala en una oración.",
  "Escribe un párrafo sobre un animal sin repetir ninguna palabra importante.")

L(OA18, 5,
  "Este cuaderno, lápiz y los borradores y comentarios escritos en cada ejercicio.",
  "Aprenderé a dar y recibir sugerencias de un compañero para mejorar un texto y a decidir cuáles usar.",
  ["Sé revisar el sentido, los párrafos y los conectores.", "Sé escuchar con respeto."],
  ["Un compañero puede ayudarte a ver lo que tú no ves. Una buena sugerencia dice qué mejorar y cómo. Por ejemplo: «En el segundo párrafo falta decir cuándo ocurrió». Una sugerencia vaga como «está mal» no ayuda a mejorar.",
   "Al dar sugerencias, comienza por algo que funciona, luego señala una mejora concreta y propone una forma de lograrla. Habla con respeto y habla del texto, no de la persona. Al recibir sugerencias, escucha sin interrumpir y haz preguntas si no entiendes.",
   "Tú decides qué sugerencias usar. Elige las que ayudan a cumplir tu propósito. Si una sugerencia cambia lo que quieres decir, puedes explicar por qué no la usas. Después de editar, vuelve a leer tu texto completo."],
  [("sugerencia", "consejo para mejorar algo"), ("retroalimentación", "comentarios que ayudan a mejorar un trabajo"), ("concreta", "clara y precisa"), ("respeto", "tratar bien a los demás y a sus trabajos")],
  [("Reconocer una sugerencia útil", "Opción A: «Tu texto está mal». Opción B: «Falta decir cuándo ocurrió el paseo». ¿Cuál ayuda más?", ["A no dice qué mejorar.", "B dice qué falta."], "Opción B"),
   ("Decidir qué sugerencias usar", "Tu propósito es invitar. Te sugieren: «Agrega la hora» y «Cuenta de qué color es tu perro». ¿Cuál usas?", ["Para invitar necesitas la hora.", "El color del perro no ayuda a invitar."], "Agrego la hora")],
  [("Decir «está mal» sin explicar.", "El otro no sabe qué cambiar.", "Dile qué mejorar y cómo."), ("Aceptar todas las sugerencias sin pensar.", "Algunas no ayudan al propósito.", "Elige las que sirven.")],
  ([E("Una sugerencia útil dice qué mejorar y cómo. Responde verdadero o falso.", "Verdadero", "Eso la hace concreta."),
    E("Al dar una sugerencia, ¿se habla del texto o de la persona?", "Del texto", "La crítica es al trabajo, no a la persona."),
    E("Cuando recibes una sugerencia, ¿debes escucharla sin interrumpir? Responde sí o no.", "Sí", "Escuchar es parte del respeto.")],
   [E("¿Cuál es más concreta: «Agrega la hora de la reunión» o «Mejora tu texto»?", "Agrega la hora de la reunión", "Dice exactamente qué agregar."),
    E("Un compañero dice: «Tu primer párrafo cuenta bien el paseo, pero el segundo repite la misma idea». ¿Empezó por algo que funciona? Responde sí o no.", "Sí", "Primero valoró el primer párrafo."),
    E("Te sugieren cambiar «cosa» por una palabra precisa. ¿Esa sugerencia mejora el vocabulario o la ortografía?", "El vocabulario", "Se trata de la precisión de las palabras.")],
   [E("Lee el texto: «Fuimos a la playa. Nadamos. Comimos». Un compañero sugiere agregar cuándo fueron. ¿Qué agregas: «El sábado» o «Con mi perro azul»?", "El sábado", "Responde a la sugerencia: cuándo."),
    E("Te dicen: «El texto es largo». ¿Qué pregunta le haces para entender mejor: «¿Qué parte puedo quitar?» o «¿Por qué eres así?»", "¿Qué parte puedo quitar?", "Es una pregunta sobre el texto."),
    E("Tu propósito es explicar cómo plantar un poroto. Te sugieren: «Cuenta del cumpleaños de tu hermano». ¿La usas? Responde sí o no.", "No", "No ayuda al propósito de explicar.")],
   [E("Dos niños comentan un texto. Uno dice «No me gustó». Otro dice «Me gustó el final; el inicio podría presentar mejor al personaje». ¿Cuál comentario ayuda más a mejorar?", "El segundo", "Dice qué falla y qué sirve."),
    E("Un niño usa una sugerencia que cambia el sentido de su texto y ya no cumple su propósito. ¿Fue buena idea usarla? Responde sí o no.", "No", "Las sugerencias deben ayudar al propósito.")],
   [E("Lee el comentario: «Tu carta es clara. Podrías agregar el día para que se entienda cuándo es la reunión». ¿Cuántas partes tiene (algo que funciona y una mejora)? Escribe el número.", "2", "Una parte valora y la otra propone mejorar."),
    E("Recibes tres sugerencias: A) agregar la fecha, B) quitar una oración repetida, C) pintar todas las letras de verde. Tu propósito es informar. Escribe las letras de las dos que usas.", "A y B", "Mejoran el sentido; pintar las letras no ayuda a informar.")]),
  [E("Tu compañero te dice: «Está desordenado». ¿Qué le pides para entender mejor: que te diga qué parte y cómo ordenarla o que se quede callado?", "Que me diga qué parte y cómo ordenarla", "Una sugerencia útil es concreta.")],
  [E("¿Qué debe tener una buena sugerencia?", "Decir qué mejorar y cómo", "Eso la hace concreta."),
   E("Al recibir una sugerencia, ¿quién decide si la usa?", "El autor del texto", "Cada uno decide para cumplir su propósito."),
   E("Después de editar con sugerencias, ¿qué hago?", "Releo el texto completo", "Compruebo que quedó mejor.")],
  ("Lee este borrador: «Mi perro se llama Luna. Es blanca. Es blanca y le gusta correr. Ayer hizo una cosa y todos reímos». Escribe dos sugerencias para su autor: una que diga qué funciona y otra que diga una mejora concreta y cómo hacerla. Luego reescribe el borrador usando tu sugerencia de mejora.", "Sugerencia 1: Tu primera oración presenta bien a tu perro. Sugerencia 2: Se repite «es blanca»; podrías unirlas y cambiar «cosa» por lo que hizo.", ["una sugerencia positiva", "una mejora concreta con propuesta", "versión nueva aplicada"], ["dos sugerencias y una versión nueva en el cuaderno"], ["comentarios vagos", "criticar a la persona"], "Entrega tus sugerencias a otra persona y pregúntale si le sirvieron."),
  "Dile a un familiar una cosa que funciona y una mejora de un texto corto que lea.",
  "Pide a un compañero que revise un texto tuyo, anota sus sugerencias y decide cuáles usas.")

# ------------------------------------------------------------------ OA 19
L(OA19, 1,
  "Este cuaderno, lápiz y las oraciones escritas en cada ejercicio.",
  "Aprenderé a encontrar los adverbios y a ver qué precisan en una oración.",
  ["Sé reconocer verbos.", "Sé responder cómo, cuándo y dónde sobre una acción."],
  ["El adverbio es una palabra que acompaña al verbo y dice cómo, cuándo, dónde o cuánto ocurre la acción. Por ejemplo, en «Ana canta fuerte», fuerte dice cómo canta. Los adverbios no cambian por género ni por número: se escribe «Ana camina rápido» y «Los niños caminan rápido».",
   "Hay adverbios de modo (bien, mal, despacio, rápido), de tiempo (hoy, ayer, mañana, siempre, nunca), de lugar (aquí, allí, cerca, lejos, arriba) y de intensidad (muy, poco, mucho). Para encontrarlos, pregúntale al verbo: ¿cómo?, ¿cuándo?, ¿dónde?, ¿cuánto?",
   "Los adverbios dan precisión. «Llegó» dice poco. «Llegó temprano» dice cuándo. «Llegó contento» no es adverbio, porque «contento» describe a quien llegó, no a la acción. En esta clase, busca palabras que respondan a las preguntas sobre el verbo. Muchos adverbios de modo terminan en -mente, como lentamente o tranquilamente."],
  [("adverbio", "palabra que precisa cómo, cuándo, dónde o cuánto ocurre una acción"), ("modo", "cómo ocurre algo"), ("tiempo", "cuándo ocurre algo"), ("lugar", "dónde ocurre algo"), ("intensidad", "cuánto o con qué fuerza ocurre algo")],
  [("Encontrar el adverbio", "En «Mi hermana canta fuerte», ¿cuál es el adverbio?", ["El verbo es «canta».", "Pregunto: ¿cómo canta?", "Responde «fuerte»."], "Fuerte"),
   ("Clasificar el adverbio", "En «Mañana iremos a la plaza», ¿qué tipo de adverbio es «mañana»?", ["Dice cuándo ocurre la acción.", "Eso es tiempo."], "De tiempo")],
  [("Pensar que todo lo que describe es adverbio.", "Si describe a una persona o cosa, es adjetivo.", "Pregúntale al verbo: ¿cómo?, ¿cuándo?, ¿dónde?, ¿cuánto?"), ("Cambiar el adverbio a plural.", "Los adverbios no cambian de género ni de número.", "Escribe «caminan rápido», no «caminan rápidos».")],
  ([E("El adverbio acompaña al verbo y dice cómo, cuándo, dónde o cuánto. Responde verdadero o falso.", "Verdadero", "Esa es su función."),
    E("En «El gato duerme arriba», ¿cuál es el adverbio?", "Arriba", "Dice dónde duerme."),
    E("En «Ema llegó temprano», la palabra «temprano», ¿dice cuándo o dónde?", "Cuándo", "Indica el momento en que llegó.")],
   [E("En «Los niños corren mucho», ¿qué dice el adverbio «mucho»: cuánto o dónde?", "Cuánto", "Es de intensidad."),
    E("En «Pedro habla despacio», ¿qué tipo de adverbio es «despacio»?", "De modo", "Dice cómo habla."),
    E("En «Aquí hay un libro», ¿qué dice el adverbio «aquí»: lugar o tiempo?", "Lugar", "Señala dónde está el libro.")],
   [E("Escribe el adverbio de tiempo en «Hoy visitamos a la abuela».", "Hoy", "Dice cuándo visitamos."),
    E("Escribe el adverbio de lugar en «La pelota quedó lejos».", "Lejos", "Dice dónde quedó."),
    E("¿Cuántos adverbios hay en «Ayer corrí muy rápido»? (Cuenta ayer, muy y rápido.)", "3", "Ayer es tiempo, muy intensidad y rápido modo.")],
   [E("Una de estas oraciones tiene un adverbio: «Ana es una niña feliz» y «Ana canta fuerte». ¿Cuál es?", "Ana canta fuerte", "Fuerte dice cómo canta; feliz describe a la niña."),
    E("¿Se puede decir «Las niñas caminan rápidas» si «rápido» es adverbio de modo? Responde sí o no.", "No", "El adverbio no cambia de género ni de número.")],
   [E("En «Siempre llegamos temprano», ¿cuántos adverbios hay?", "2", "Siempre y temprano."),
    E("Observa «Ella respondió bien, pero lentamente». ¿Cuál es el adverbio que acaba en -mente?", "Lentamente", "Es el adverbio de modo formado con -mente.")]),
  [E("Escribes: «Mi perro duerme tranquilamente aquí». ¿Cuántos adverbios hay?", "2", "Tranquilamente y aquí.")],
  [E("¿Qué palabra acompaña el verbo y dice cómo, cuándo, dónde o cuánto?", "El adverbio", "Esa es su función."),
   E("¿Cambia el adverbio de género o número? Responde sí o no.", "No", "Los adverbios son invariables."),
   E("¿A qué pregunta responde un adverbio de lugar?", "¿Dónde?", "Dice el lugar de la acción.")],
  ("Lee esta oración: «Ayer llegamos tarde y caminamos lento hasta aquí». Anota en el cuaderno cada adverbio y escribe al lado qué precisa (modo, tiempo, lugar o intensidad). Después escribe una oración propia con un adverbio de modo y otro de lugar.", "Ayer: tiempo; tarde: tiempo; lento: modo; aquí: lugar. Mi oración: «El gato camina despacio allí».", ["encuentra todos los adverbios", "dice qué precisa cada uno", "escribe una oración propia"], ["lista y oración en el cuaderno"], ["tomar adjetivos como adverbios", "olvidar alguno"], "Compara tu lista con la de otra persona."),
  "Lee en voz alta una oración con adverbios y di qué precisa cada uno.",
  "Escribe cinco oraciones, cada una con un adverbio de un tipo distinto.")

L(OA19, 2,
  "Este cuaderno, lápiz y las oraciones escritas en cada ejercicio.",
  "Aprenderé a cambiar el adverbio de modo, tiempo o lugar para decir algo distinto con las mismas palabras.",
  ["Sé encontrar adverbios y decir qué precisan."],
  ["Si cambias el adverbio, cambia lo que dice la oración. «Ema corre rápido» y «Ema corre despacio» tienen sentidos distintos. Para que la oración siga teniendo sentido, el nuevo adverbio debe ser del mismo tipo: de modo por modo, de tiempo por tiempo y de lugar por lugar.",
   "Si cambias un adverbio de tiempo, a veces debes cambiar también el verbo. «Ayer jugamos» y «Mañana jugaremos»: ayer va con pasado y mañana con futuro. Con adverbios de modo y lugar casi nunca cambia el verbo.",
   "También puedes agregar un adverbio para precisar. «El tren llegó» se vuelve más claro con «El tren llegó temprano». Así el lector sabe más detalles. Elige el adverbio que diga justo lo que quieres informar."],
  [("reemplazar", "poner una palabra en lugar de otra"), ("precisar", "decir con más exactitud"), ("antónimo", "palabra de significado contrario"), ("mismo tipo", "que responde la misma pregunta: cómo, cuándo, dónde o cuánto")],
  [("Cambiar el modo", "Cambia «Ema corre rápido» para decir lo contrario.", ["«Rápido» dice cómo corre.", "El contrario de rápido es despacio."], "Ema corre despacio"),
   ("Cambiar el tiempo", "Cambia «Ayer jugamos» para decir que ocurrirá luego.", ["Ayer es pasado.", "El adverbio para el futuro es mañana.", "El verbo cambia: jugaremos."], "Mañana jugaremos")],
  [("Cambiar un adverbio de modo por uno de lugar.", "La oración pierde su sentido.", "Reemplaza por uno del mismo tipo."), ("Cambiar «ayer» por «mañana» y dejar el verbo igual.", "El tiempo del verbo debe coincidir.", "Ajusta el verbo.")],
  ([E("Para decir lo contrario de «cerca», ¿qué adverbio usas: lejos o despacio?", "Lejos", "Ambos son de lugar."),
    E("Si cambias «rápido» por «despacio», ¿cambia el sentido de la oración? Responde sí o no.", "Sí", "Son palabras contrarias."),
    E("¿«Tarde» es antónimo de «temprano»? Responde sí o no.", "Sí", "Los dos hablan de tiempo y significan lo opuesto.")],
   [E("Cambia «Vive cerca» para decir lo contrario. ¿Cuál es: «Vive lejos» o «Vive despacio»?", "Vive lejos", "Reemplaza el lugar por otro lugar."),
    E("En «Habla bien», cambia «bien» por su contrario de modo. Elige: mal o mañana.", "Mal", "Mal es el contrario de bien."),
    E("En «Llegó temprano», cambia el adverbio por uno de tiempo contrario. Elige: tarde o aquí.", "Tarde", "Es el contrario de temprano.")],
   [E("Cambia «Ayer comimos pizza» para hablar del futuro. Escribe el adverbio nuevo y el verbo: ¿«Mañana comeremos pizza» o «Mañana comimos pizza»?", "Mañana comeremos pizza", "El verbo debe ir en futuro."),
    E("En «El perro duerme arriba», cambia el adverbio para decir que duerme en la parte baja. Elige: abajo o rápido.", "Abajo", "Es el lugar contrario."),
    E("En «Camina muy lentamente», reemplaza «lentamente» por un adverbio de modo de significado contrario. Elige: rápidamente o aquí.", "Rápidamente", "Es el contrario de modo.")],
   [E("Un niño reemplaza «despacio» por «ayer» en «Camina despacio». ¿Mantiene el sentido? Responde sí o no.", "No", "Cambió modo por tiempo."),
    E("En «Hoy llueve fuerte», ¿puedes reemplazar «hoy» por «ayer» sin cambiar el verbo? Responde sí o no.", "No", "El verbo debe ir en pasado: llovió.")],
   [E("Cambia los tres adverbios: «Hoy canta bien aquí». Elige el resultado correcto: «Ayer cantó mal allí» o «Ayer cantó mal rápido».", "Ayer cantó mal allí", "Cada adverbio se cambió por otro del mismo tipo."),
    E("Agrega un adverbio de lugar a «El libro está»: elige la mejor opción: «El libro está encima» o «El libro está lentamente».", "El libro está encima", "Encima es de lugar.")]),
  [E("Para contar lo que pasó antes, ¿cuál sirve: «Ayer fuimos al parque» o «Ayer vamos al parque»?", "Ayer fuimos al parque", "Ayer pide el verbo en pasado: fuimos.")],
  [E("Al cambiar un adverbio, ¿debe ser del mismo tipo? Responde sí o no.", "Sí", "Así la oración conserva sentido."),
   E("¿Cuál es el contrario de «arriba»?", "Abajo", "Los dos son adverbios de lugar."),
   E("¿Qué debes cambiar al reemplazar «ayer» por «mañana»?", "El tiempo del verbo", "Pasado y futuro son distintos.")],
  ("Lee: «Hoy leemos aquí en silencio». Escribe tres versiones cambiando solo un adverbio cada vez: una que cambie el lugar, otra que cambie el modo y otra que cambie el tiempo (cuida el verbo). Subraya el adverbio que cambiaste.", "«Hoy leemos allí en silencio»; «Hoy leemos aquí en voz alta»; «Mañana leeremos aquí en silencio».", ["cambia lugar, modo y tiempo", "mantiene el sentido de cada oración", "ajusta el verbo cuando cambia el tiempo"], ["tres oraciones en el cuaderno"], ["cambiar por un adverbio de otro tipo", "no ajustar el verbo"], "Lee tus oraciones a otra persona y pregunta si cada una tiene sentido."),
  "Di en voz alta la misma oración con un adverbio de lugar distinto.",
  "Escribe una oración con un adverbio y cámbiala de modo, tiempo y lugar.")

L(OA19, 3,
  "Este cuaderno, lápiz y las oraciones escritas en cada ejercicio.",
  "Aprenderé a comparar adverbios parecidos y a elegir el que mejor dice lo que quiero comunicar.",
  ["Sé reemplazar adverbios por otros del mismo tipo."],
  ["Dos adverbios pueden ser parecidos, pero no siempre dicen lo mismo. «Poco», «bastante» y «mucho» son de intensidad, pero muestran cantidades distintas. «A veces», «casi siempre» y «siempre» hablan de frecuencia, es decir, de cuántas veces ocurre algo.",
   "«Siempre» significa todas las veces. «Casi siempre» significa casi todas. «A veces» significa algunas. «Nunca» significa ninguna vez. Elegir el adverbio exacto es dar un matiz, es decir, una diferencia pequeña de significado.",
   "Por eso, ordenar los adverbios por intensidad ayuda a elegir bien. De menos a más: nada, poco, bastante, mucho. Otra tarea es decidir si «lentamente» y «despacio» pueden usarse en el mismo lugar. Casi siempre sí, y solo cambia un poco el estilo."],
  [("matiz", "diferencia pequeña de significado"), ("frecuencia", "cuántas veces ocurre algo"), ("intensidad", "cuánto ocurre algo"), ("siempre", "todas las veces"), ("nunca", "ninguna vez")],
  [("Ordenar por intensidad", "Ordena de menos a más: mucho, poco, bastante.", ["Poco es lo menor.", "Luego bastante.", "Al final mucho."], "poco, bastante, mucho"),
   ("Elegir el matiz", "Llueve algunas veces al año. ¿Qué adverbio corresponde: nunca, a veces o siempre?", ["Algunas veces no es nunca ni todas.", "Corresponde «a veces»."], "a veces")],
  [("Pensar que «casi siempre» y «siempre» son iguales.", "«Casi siempre» deja algunas excepciones.", "Usa «siempre» solo si es todas las veces."), ("Usar «mucho» cuando quieres decir «bastante».", "El matiz cambia la cantidad.", "Revisa qué cantidad quieres expresar.")],
  ([E("«Siempre» significa todas las veces. Responde verdadero o falso.", "Verdadero", "Esa es su definición."),
    E("¿Cuál es el mayor: «poco» o «mucho»?", "Mucho", "Mucho indica más cantidad que poco."),
    E("«Nunca» significa que algo ocurre ninguna vez. Responde verdadero o falso.", "Verdadero", "Nunca es la ausencia total.")],
   [E("Ordena de menos a más: bastante, poco, mucho. ¿Cuál queda en medio?", "Bastante", "El orden es poco, bastante, mucho."),
    E("«Desayuno casi siempre en casa.» ¿Desayuno todos los días en casa? Responde sí o no.", "No", "«Casi siempre» deja algunas excepciones."),
    E("Completa con el matiz correcto: «Me acuesto temprano todos los días: me acuesto ___ temprano». Opciones: siempre, nunca.", "siempre", "Todos los días equivale a todas las veces.")],
   [E("Un niño estudió 5 días de 5. ¿Qué adverbio es más exacto: siempre o a veces?", "Siempre", "Estudió todos los días de esos cinco."),
    E("Un niño leyó 1 día de 5. ¿Qué adverbio es más exacto: casi siempre o a veces?", "A veces", "Fue solo una vez."),
    E("Completa: «El helado estaba ___ frío; mi lengua casi se congela». Opciones: muy, poco.", "muy", "La frase indica mucho frío.")],
   [E("Ema dice: «Siempre llego tarde», pero llegó temprano el lunes. ¿Es exacto «siempre»? Responde sí o no.", "No", "Hay una excepción, así que no fue todas las veces."),
    E("¿Qué adverbio expresa una intensidad menor: «bastante» o «poco»?", "Poco", "Poco es menos que bastante.")],
   [E("Lee: «Tomás hizo la tarea el lunes, el martes y el miércoles, pero no el jueves ni el viernes». ¿Qué adverbio es más exacto: siempre o a veces?", "A veces", "Algunos días sí y otros no."),
    E("Elige el orden correcto de menor a mayor frecuencia: «nunca, a veces, casi siempre, siempre» o «siempre, casi siempre, a veces, nunca».", "Nunca, a veces, casi siempre, siempre", "Va de ninguna vez a todas las veces.")]),
  [E("Dices: «Mi hermano ___ ayuda con las tareas; hay semanas en que sí y otras en que no». Elige el adverbio más exacto: siempre o a veces.", "A veces", "Algunas semanas sí y otras no.")],
  [E("¿Qué es un matiz?", "Una diferencia pequeña de significado", "Cambia un poco lo que se dice."),
   E("¿Qué adverbio significa todas las veces?", "Siempre", "Esa es su definición."),
   E("¿Qué adverbio indica la intensidad mayor: poco, bastante o mucho?", "Mucho", "Es la mayor cantidad.")],
  ("Completa en tu cuaderno tres oraciones sobre ti, usando un adverbio distinto de frecuencia en cada una: «Yo ___ leo antes de dormir», «Yo ___ juego en la plaza» y «Yo ___ como verduras». Elige siempre, casi siempre, a veces o nunca y explica por qué ese es el más exacto.", "Yo casi siempre leo antes de dormir, porque lo hago casi todos los días.", ["completa tres oraciones", "elige adverbios exactos", "explica un motivo"], ["tres oraciones y una explicación"], ["usar «siempre» sin que sea cierto", "no explicar"], "Comparte una oración con otra persona y comprueba si el adverbio es exacto."),
  "Di en voz alta qué haces siempre y qué no haces nunca.",
  "Escribe cuatro oraciones con poco, bastante, mucho y nada, sobre un mismo tema.")

L(OA19, 4,
  "Este cuaderno, lápiz y las oraciones escritas en cada ejercicio.",
  "Aprenderé a combinar adverbios en una oración sin recargarla.",
  ["Sé elegir el adverbio exacto.", "Sé encontrar adverbios en una oración."],
  ["Una oración puede llevar más de un adverbio si aportan información distinta. «Ayer llegamos temprano» tiene dos: ayer (qué día) y temprano (a qué hora). Pero demasiados adverbios cansan: «Ayer hoy llegamos temprano aquí muy ya» queda confuso.",
   "Una buena regla es usar un adverbio por cada pregunta que quieres responder: ¿cuándo?, ¿dónde?, ¿cómo? Si dos adverbios dicen lo mismo, deja el mejor. También evita repetir muchos adverbios terminados en -mente en la misma oración: «lenta y silenciosamente» suena mejor que «lentamente y silenciosamente».",
   "Para recargar menos, a veces conviene dividir en dos oraciones o usar una expresión en vez de otro adverbio. Lee en voz alta tu oración. Si cansa, quita el adverbio que menos informa."],
  [("combinar", "usar juntos"), ("recargar", "poner más de lo necesario"), ("información nueva", "dato que la oración todavía no decía"), ("-mente", "terminación de muchos adverbios de modo")],
  [("Combinar sin recargar", "Combina: «Ana llegó» + ayer + temprano. ¿Cómo queda?", ["Ayer dice cuándo.", "Temprano dice cómo fue la hora.", "Los dos aportan datos distintos."], "Ayer, Ana llegó temprano"),
   ("Quitar el que sobra", "«Llegó hoy ahora mismo». ¿Qué adverbio sobra?", ["Hoy y ahora dicen cuándo.", "Dicen casi lo mismo.", "Dejo uno."], "Hoy (o ahora)")],
  [("Poner un adverbio en cada espacio.", "La oración se vuelve pesada.", "Usa solo los que informan algo nuevo."), ("Repetir varios adverbios con -mente.", "Suena repetitivo.", "Usa solo el último con -mente.")],
  ([E("Una oración puede tener dos adverbios si aportan información distinta. Responde verdadero o falso.", "Verdadero", "Cada uno responde una pregunta distinta."),
    E("«Ayer llegamos temprano»: ¿cuántos adverbios hay?", "2", "Ayer y temprano."),
    E("Si dos adverbios dicen lo mismo, ¿dejas ambos o solo el mejor?", "Solo el mejor", "Repetir no agrega información.")],
   [E("¿Cuál oración está menos recargada: «Corre rápido hoy» o «Corre rápido rápidamente hoy mismo ya»?", "Corre rápido hoy", "Tiene dos adverbios que dicen cosas distintas."),
    E("En «Camina lentamente y silenciosamente», ¿qué conviene hacer con las terminaciones -mente?", "Dejar solo la última: lenta y silenciosamente", "Evita repetir la terminación."),
    E("¿Qué adverbios de «Vive aquí cerca» dicen casi lo mismo?", "Aquí y cerca", "Ambos hablan del lugar.")],
   [E("Combina «Leí un cuento» con ayer y despacio. ¿Cuál queda mejor: «Ayer leí un cuento despacio» o «Ayer despacio hoy leí un cuento»?", "Ayer leí un cuento despacio", "Combina dos adverbios distintos sin repetir."),
    E("En «Llegó hoy ahora», hoy y ahora dicen casi lo mismo. ¿Cuántos adverbios dejas para no repetir?", "1", "Ambos responden cuándo; basta uno."),
    E("Mejora «El perro corre rápidamente y velozmente». Elige: «El perro corre rápidamente» o «El perro corre despacio».", "El perro corre rápidamente", "Se quita el adverbio repetido sin cambiar el sentido.")],
   [E("Dos niños combinan adverbios. Uno escribe «Hoy cantó bien». El otro «Hoy cantó bien muy mucho siempre». ¿Cuál es más claro?", "Hoy cantó bien", "No está recargada."),
    E("Si una oración tiene tres adverbios que responden cuándo, dónde y cómo, ¿está recargada? Responde sí o no.", "No", "Cada uno aporta algo distinto.")],
   [E("Combina en una oración: «Mi perro duerme». Agrega aquí y tranquilamente. ¿Cuál queda mejor: «Mi perro duerme tranquilamente aquí» o «Mi perro duerme aquí tranquilamente aquí»?", "Mi perro duerme tranquilamente aquí", "No repite adverbios."),
    E("¿Cuántos adverbios hay en «Mañana saldremos temprano de aquí»?", "3", "Mañana, temprano y aquí.")]),
  [E("Escribes: «Los patos nadan hoy aquí muy tranquilamente lentamente». Para mejorar, ¿qué conviene hacer: quitar los adverbios que repiten o agregar más?", "Quitar los adverbios que repiten", "Solo deben quedar los que informan algo nuevo.")],
  [E("¿Cuántos adverbios caben en una oración? Responde: los que aporten información nueva o cualquier cantidad.", "Los que aporten información nueva", "Más no es mejor."),
   E("¿Qué hago si dos adverbios dicen lo mismo?", "Dejo solo uno", "Así evito repetir."),
   E("¿Conviene repetir adverbios con -mente?", "No", "Hace la oración pesada.")],
  ("Combina estas ideas en dos oraciones sin recargar: «El tren llega». Adverbios: mañana, temprano, aquí, muy, lentamente, ahora, hoy. Elige tres que no se contradigan ni repitan y escribe una oración. Luego escribe otra oración distinta con otros dos adverbios de la lista.", "«Mañana el tren llega temprano aquí». «El tren llega lentamente hoy».", ["usa adverbios de tipos distintos", "no repite significados", "las oraciones suenan naturales"], ["dos oraciones en el cuaderno"], ["poner todos los adverbios", "repetir tiempo"], "Lee en voz alta tus oraciones: si cansan, quita un adverbio."),
  "Lee una oración con muchos adverbios y tacha los que no informan.",
  "Escribe un párrafo de tres oraciones con a lo más dos adverbios por oración.")

L(OA19, 5,
  "Este cuaderno, lápiz y los textos escritos en cada ejercicio.",
  "Aprenderé a revisar un texto propio para precisar o mejorar el uso de adverbios.",
  ["Sé combinar y cambiar adverbios.", "Sé revisar el sentido de un texto."],
  ["Revisar los adverbios de tu texto ayuda a precisar. Puedes preguntarte: ¿hay acciones que necesitan decir cuándo, dónde o cómo? ¿Hay adverbios repetidos o que no ayudan? ¿Hay un adverbio que dice menos de lo que quiero?",
   "Para revisar, subraya los verbos y mira qué dicen sobre cada acción. Si una acción dice poco, agrega un adverbio. Si un adverbio se repite, cámbialo por otro. Si un adverbio sobra, quítalo. Revisa también que sean del tipo correcto.",
   "Después de cambiar, vuelve a leer en voz alta. El texto debe sonar claro y mantener su sentido. Una buena revisión deja el texto más preciso sin recargarlo, y siempre pensando en el lector."],
  [("revisión", "leer de nuevo para mejorar"), ("precisar", "decir con más exactitud"), ("sobrar", "haber algo de más"), ("lector", "la persona que leerá el texto")],
  [("Agregar un adverbio que precisa", "«El perro llegó». ¿Cómo lo precisas?", ["Pregunto: ¿cuándo, cómo o dónde?", "Puedo decir «rápido»."], "El perro llegó rápido"),
   ("Cambiar un adverbio repetido", "«Hablaba suavemente y caminaba suavemente». ¿Cómo mejoras?", ["Repite «suavemente».", "Cambio uno por otro de modo.", "Camina despacio."], "Hablaba suavemente y caminaba despacio")],
  [("Agregar adverbios sin saber qué informan.", "Recarga el texto.", "Pregunta qué dato nuevo aporta."), ("No volver a leer el texto después de cambiar.", "Puede quedar sin sentido.", "Léelo completo en voz alta.")],
  ([E("Revisar los adverbios sirve para precisar el texto. Responde verdadero o falso.", "Verdadero", "Esa es la meta."),
    E("Si un adverbio sobra, ¿lo dejas o lo quitas?", "Lo quito", "No aporta información nueva."),
    E("Después de revisar, ¿se vuelve a leer el texto? Responde sí o no.", "Sí", "Se comprueba que quedó mejor.")],
   [E("«Luis llegó.» ¿Cuál mejora la precisión: «Luis llegó temprano» o «Luis llegó llegó»?", "Luis llegó temprano", "Agrega cuándo llegó."),
    E("«Canta bien bien muy bien.» ¿Qué conviene cambiar: dejar uno solo de los que repiten o agregar otro?", "Dejar uno solo de los que repiten", "Se evita la repetición."),
    E("En «Dejé el libro», ¿qué adverbio precisa el lugar: aquí o rápido?", "Aquí", "Es un adverbio de lugar.")],
   [E("Revisa: «El zorro caminó. El zorro saltó. El zorro corrió». ¿Qué adverbio agregarías para precisar: «sigilosamente» o «ayer mañana»?", "Sigilosamente", "Precisa cómo se mueve el zorro."),
    E("Lee: «Hoy ayer mañana jugué». ¿Cuál es el error: adverbios de tiempo contradictorios o falta de lugar?", "Adverbios de tiempo contradictorios", "Hoy, ayer y mañana no pueden ir juntos."),
    E("Lee: «Escribí con cuidado. Escribí con cuidado la carta». Mejora con un solo adverbio: «Escribí cuidadosamente la carta» o «Escribí la carta con cuidado cuidado».", "Escribí cuidadosamente la carta", "Resuelve la repetición con un solo adverbio.")],
   [E("Un niño agrega adverbios a cada verbo de su texto y queda recargado. ¿Qué hace mejor: dejar solo los que informan o dejar todos?", "Dejar solo los que informan", "Así el texto queda claro."),
    E("Un texto dice «Llegó» tres veces sin más datos. Revisas. ¿Qué agregas para variar y precisar?", "Adverbios distintos de tiempo y modo", "Así el texto da más información.")],
   [E("En «Caminamos lentamente. Hablamos lentamente. Comimos lentamente» dejas el primer adverbio igual. ¿Cuántos cambias por otro adverbio de modo para no repetir?", "2", "Quedan dos repeticiones del primero."),
    E("Un texto dice: «Nos fuimos tarde y llegamos temprano». ¿Qué adverbios son de tiempo y cuántos hay?", "Tarde y temprano; 2", "Los dos responden cuándo.")]),
  [E("Revisas el aviso «Nos reunimos». ¿Qué datos de tiempo y lugar le agregarías con adverbios: «hoy» y «aquí» o «lento» y «mucho»?", "Hoy y aquí", "Dicen cuándo y dónde.")],
  [E("¿Qué preguntas me hago al revisar adverbios?", "Si precisan, si se repiten, si sobran", "Así reviso el texto."),
   E("¿Qué hago con un adverbio repetido?", "Lo cambio por otro", "Así evito repetir."),
   E("¿Dónde compruebo que el texto quedó claro?", "Leyéndolo en voz alta", "Se escucha si suena bien.")],
  ("Revisa este texto: «Ayer fui al parque. Jugué mucho. Corrí mucho. Volví a casa». Reescríbelo en tu cuaderno agregando tres adverbios que precisen cuándo, dónde y cómo, sin repetir ninguno. Subraya los adverbios nuevos y anota qué precisa cada uno.", "«Ayer fui temprano al parque. Jugué mucho allí. Corrí rápido. Volví a casa cansado». (temprano: tiempo; allí: lugar; rápido: modo)", ["agrega tres adverbios distintos", "dice qué precisa cada uno", "no recarga el texto"], ["texto reescrito y subrayado"], ["agregar adverbios repetidos", "no explicar qué precisan"], "Lee el texto a otra persona y pregunta si imagina mejor la escena."),
  "Subraya los adverbios de un texto corto y di cuál es el más preciso.",
  "Elige un texto tuyo y mejora tres verbos con adverbios.")
